  const HOST_BORDER = { "Germany":"#5dff73","United States":"#5dff73","Japan":"#5dff73","Brazil":"#5dff73","United Arab Emirates":"#ffb63d","South Africa":"#ff5a52" };

  // ── vector / projection ────────────────────────────────────────────────────
  const D2R = Math.PI / 180;
  function toVec(lat, lng) { const p = lat*D2R, l = lng*D2R; return [Math.cos(p)*Math.sin(l), Math.sin(p), Math.cos(p)*Math.cos(l)]; }
  function slerp(a, b, t) { let d = a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; d = Math.max(-1, Math.min(1, d)); const o = Math.acos(d); if (o < 1e-4) return a.slice(); const s = Math.sin(o), c1 = Math.sin((1-t)*o)/s, c2 = Math.sin(t*o)/s; return [a[0]*c1+b[0]*c2, a[1]*c1+b[1]*c2, a[2]*c1+b[2]*c2]; }
  let seed = 20260718; const rand = () => { seed = (seed*1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };

  // ── state populated from the API (or fallback) ─────────────────────────────
  let HUB = null, GATEWAYS = [], gwByRegion = {}, REGIONS = [], PEERS = [], NODES = [], COUNTRIES = [];
  let LAND = [], MERIDIANS = [], PARALLELS = [];

  function buildStaticGeometry() {
    for (let lat = -58; lat <= 80; lat += 2.5) for (let lng = -180; lng < 180; lng += 2.5) if (isLand(lat, lng)) LAND.push(toVec(lat, lng));
    for (let lng = -150; lng <= 180; lng += 30) { const p = []; for (let lat = -80; lat <= 80; lat += 5) p.push(toVec(lat, lng)); MERIDIANS.push(p); }
    for (let lat = -60; lat <= 60; lat += 30) { const p = []; for (let lng = -180; lng <= 180; lng += 5) p.push(toVec(lat, lng)); PARALLELS.push(p); }
    COUNTRIES = Object.entries(BORDERS).map(([name, rings]) => {
      const rv = rings.map(r => r.map(([lng,lat]) => toVec(lat,lng)));
      let sx=0,sy=0,sz=0; rv.forEach(r=>r.forEach(v=>{ sx+=v[0]; sy+=v[1]; sz+=v[2]; }));
      const m = Math.hypot(sx,sy,sz)||1;
      return { name, rings: rv, centroid:[sx/m,sy/m,sz/m], flag: FLAGS[name], border: HOST_BORDER[name] || "rgba(140,205,235,0.45)", host: !!HOST_BORDER[name] };
    });
  }

  function ingest(topo, peers) {
    const h = topo.hub || {};
    HUB = { role: 'hub', name: h.label || 'Pool Hub', v: (h.lat != null) ? toVec(h.lat, h.lng) : toVec(20, 0) };
    GATEWAYS = (topo.gateways || []).filter(g => g.lat != null).map(g => ({
      role: 'gw', region: g.region, name: g.label || g.region, status: g.status || 'connected',
      miners: g.miners || 0, _feed: g.miners || 0, v: toVec(g.lat, g.lng)
    }));
    gwByRegion = {}; GATEWAYS.forEach(g => { gwByRegion[g.region] = g; });
    REGIONS = (topo.countries || []).filter(c => c.lat != null).map(c => {
      const gw = gwByRegion[c.gateway] || GATEWAYS[0] || null;
      return { role: 'region', name: c.country, cc: c.country_code, n: c.miners, gw: c.gateway,
        v: toVec(c.lat, c.lng), gwv: gw ? gw.v : (HUB ? HUB.v : toVec(20,0)), gwStatus: gw ? gw.status : 'connected' };
    });
    NODES = [ HUB, ...GATEWAYS, ...REGIONS ];

    // peers → twinkle points. Prefer server-positioned points; else scatter on land.
    PEERS = [];
    const pts = (peers && peers.points) || [];
    if (pts.length) {
      pts.forEach(p => PEERS.push({ v: toVec(p.lat, p.lng), net: p.net || 'main', phase: rand()*6.28, spd: 0.001 + rand()*0.0035, blink: rand() < 0.28 }));
    } else {
      const total = (peers && peers.totals && peers.totals.peers) || 0;
      const want = Math.min(140, Math.max(0, total)) || (peers === FALLBACK_PEERS ? 110 : 0);
      let made = 0, guard = 0;
      while (made < want && guard++ < want*60) { const lat=-55+rand()*130, lng=-180+rand()*360; if (!isLand(lat,lng)) continue;
        PEERS.push({ v: toVec(lat,lng), net: rand()<0.75?'main':'test', phase: rand()*6.28, spd: 0.001+rand()*0.0035, blink: rand()<0.28 }); made++; }
    }
  }

  // ── canvas ──────────────────────────────────────────────────────────────────
  let cv, tip, W=0, H=0, cx=0, cy=0, baseR=0, R=0, dpr=1, zoom=1;
  function resize() { dpr = Math.min(window.devicePixelRatio || 1, 2); const rect = cv.getBoundingClientRect(); W = rect.width; H = rect.height; cv.width = Math.round(W*dpr); cv.height = Math.round(H*dpr); ctx.setTransform(dpr,0,0,dpr,0,0); cx = W/2; cy = H/2; baseR = Math.min(W,H)*0.46; }

