    const halo = ctx.createRadialGradient(cx,cy,R*0.6,cx,cy,R*1.25); halo.addColorStop(0,"rgba(93,255,115,0.05)"); halo.addColorStop(0.7,"rgba(93,255,115,0.05)"); halo.addColorStop(1,"rgba(93,255,115,0)");
